    @torch.no_grad()
    def doTTSnoUserPrompt(
        self, 
        input_ids: Optional[torch.tensor] = None,
        speaker: str = "f245",
        talker_max_new_tokens: int = 4096,
        talker_do_sample: bool = True,
        talker_top_k: int = 50,
        talker_top_p: float = 1.0,
        talker_temperature: float = 1.0,
        talker_eos_token_id: Optional[int] = None,
        talker_repetition_penalty: float = 1.05,
        **kwargs,
    ):
        shared_kwargs = {}
        talker_kwargs = {
            "max_new_tokens": talker_max_new_tokens,
            "do_sample": talker_do_sample,
            "top_k": talker_top_k,
            "top_p": talker_top_p,
            "temperature": talker_temperature,
            "eos_token_id": talker_eos_token_id if talker_eos_token_id is not None else self.config.talker_config.codec_eos_token_id,
            "repetition_penalty": talker_repetition_penalty,
            "suppress_tokens": [
                i
                for i in range(self.config.talker_config.vocab_size - 1024, self.config.talker_config.vocab_size)
                if i not in (self.config.talker_config.codec_eos_token_id,)
            ],
            "output_hidden_states": True,
            "return_dict_in_generate": True,
            "use_audio_in_video": True,
            "audio_feature_lengths": 0,
        }

        if speaker not in self.config.talker_config.spk_id:
            raise NotImplementedError(f"Speaker {speaker} not implemented")
        else:
            spk_id = self.config.talker_config.spk_id[speaker.lower()]

        thinker_embed = self.thinker.get_input_embeddings()(input_ids)
        talker_hidden = self.talker.text_projection(thinker_embed)

        tts_bos_embed, tts_eos_embed, tts_pad_embed = self.talker.text_projection(
            self.thinker.get_input_embeddings()( #Embedding需要通过tensor来访问，不能通过下标来访问
                torch.tensor(
                    [[self.config.tts_bos_token_id, self.config.tts_eos_token_id, self.config.tts_pad_token_id]],
                    device=self.thinker.device,
                    dtype=input_ids.dtype,
                )
            )
        ).chunk(3, dim=1)  # 3 * [1 1 d] chunk命令将[1x3xd]的tensor按照第1维切分

        assistant_text_hidden = torch.cat(
            (
                tts_pad_embed.expand(-1, 4, -1),
                tts_bos_embed,
                talker_hidden[:, :1],  # First text
            ),
            dim=1,
        )
        assistant_codec_hidden = self.talker.get_input_embeddings()(
            torch.tensor(
                [
                    [
                        self.config.talker_config.codec_nothink_id,
                        self.config.talker_config.codec_think_bos_id,
                        self.config.talker_config.codec_think_eos_id,
                        # self.config.talker_config.codec_spk_id,
                        spk_id,
                        self.config.talker_config.codec_pad_id,
                        self.config.talker_config.codec_bos_id,
                    ]
                ],
                device=self.talker.device,
                dtype=input_ids.dtype,
            )
        )

        talker_input_embed = assistant_text_hidden + assistant_codec_hidden
        talker_input_id = torch.empty((1, assistant_text_hidden.shape[1]), dtype=input_ids.dtype, device=assistant_text_hidden.device).fill_(self.config.tts_pad_token_id)

        trailing_text_hidden = torch.cat(
            (
                talker_hidden[:, 1:],
                tts_eos_embed,
            ),
            dim=1,
        )

        talker_result = self.talker.generate(
            inputs_embeds=talker_input_embed,
            trailing_text_hidden=trailing_text_hidden,
            tts_pad_embed=tts_pad_embed,
            talker_input_ids=talker_input_id,  # Not use input_ids to prevent repetation penalty out of bound
            **talker_kwargs,
        )
        talker_codes = torch.stack([hid[-1] for hid in talker_result.hidden_states if hid[-1] is not None], dim=1)

        return talker_codes

